/**
 * Billing report formatter. Renders records into the line format used by the
 * finance export.
 *
 * Field units and semantics follow docs/API.md as amended by
 * docs/CHANGELOG.md (newest entry wins):
 * - `amount` is an integer in cents (v2.0); rendered as yuan with exactly
 *   two decimal places.
 * - `discount` is the final discounted amount in cents (v2.1); rendered
 *   as-is, never computed from a rate.
 * - `createdAt` is UTC epoch milliseconds; `created` is rendered as an
 *   ISO-8601 timestamp with an explicit +08:00 offset (v2.3).
 */

const HEADER = 'id|name|amount|discount|created'
const UTC8_OFFSET_MS = 8 * 60 * 60 * 1000

/** Renders a cent value with exactly two decimal places. */
function renderCents(cents) {
  return (cents / 100).toFixed(2)
}

/**
 * Renders UTC epoch milliseconds as an ISO-8601 timestamp in the +08:00
 * timezone, e.g. `2026-08-30T01:00:00.000+08:00`.
 */
function renderCreatedAt(epochMs) {
  // Shifting the epoch by +08:00 and reading the UTC fields yields the
  // wall-clock time in the +08:00 timezone. toISOString() always emits a
  // trailing `Z`, so the suffix is swapped for the offset we shifted by.
  const shifted = new Date(epochMs + UTC8_OFFSET_MS)
  return `${shifted.toISOString().slice(0, -1)}+08:00`
}

export function formatReport(records) {
  const lines = [HEADER]
  for (const record of records) {
    const amount = renderCents(record.amount ?? 0)
    const discount = renderCents(record.discount ?? 0)
    const created = renderCreatedAt(record.createdAt ?? 0)
    // A missing or invalid name still renders, as an empty field
    // (docs/FORMAT.md rule 4).
    const name = record.name ?? ''
    lines.push(`${record.id}|${name}|${amount}|${discount}|${created}`)
  }
  return lines
}
